WITH scored AS (SELECT *, LEAD(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec, id) AS next_duration_sec, LAG(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec, id) AS prev_duration_sec, ROW_NUMBER() OVER (PARTITION BY session_id ORDER BY duration_sec, id) AS row_seq, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS duration_sec_avg_90d FROM web_events) SELECT id, session_id, event_type, event_time, duration_sec, next_duration_sec, prev_duration_sec, row_seq, duration_sec_avg_90d, CASE WHEN event_type RLIKE '^(search|purchase)$' THEN 'CORE' WHEN event_type RLIKE '^(page_view|click)$' THEN 'GROUP_B' ELSE 'EXTENDED' END AS event_type_zone FROM scored ORDER BY event_type DESC, row_seq DESC;
